# ==============================================================================# IOTEC MISSION CONTROL# 002_KERNEL.py# ==============================================================================import jsonimport socketimport platformimport datetimefrom pathlib import PathROOT = Path(__file__).resolve().parentCONFIG = ROOT / "MISSION_CONTROL" / "config" / "system.json"LOG = ROOT / "MISSION_CONTROL" / "logs" / "kernel.log"STATUS = ROOT / "MISSION_CONTROL" / "config" / "kernel_status.json"print("=" * 80)print("KERNEL")print("=" * 80)if CONFIG.exists():    with open(CONFIG, encoding="utf-8") as f:        system = json.load(f)else:    raise FileNotFoundError("system.json nÃ£o encontrado.")kernel = {    "kernel": "ONLINE",    "hostname": socket.gethostname(),    "python": platform.python_version(),    "platform": platform.platform(),    "boot": datetime.datetime.now().isoformat()}with open(STATUS, "w", encoding="utf-8") as f:    json.dump(kernel, f, indent=4, ensure_ascii=False)with open(LOG, "a", encoding="utf-8") as f:    f.write(        f"{datetime.datetime.now()} | KERNEL ONLINE | {socket.gethostname()}\n"    )print("[OK] Kernel iniciado")print("[OK] kernel_status.json")print("[OK] kernel.log")print("=" * 80)print("ONLINE")print("=" * 80)

